const item = $input.first().json;
const body = item.body || item;

const cuil = body.cuil;
const action = body.action;
const nombre = body.nombre;
const desde = body.desde;
const hasta = body.hasta;
const venceEnDias = body.vence_en_dias;

if (!cuil || !/^\d{11}$/.test(String(cuil))) {
  return [{ json: { error: 'CUIL invalido. Debe tener 11 digitos numericos.' } }];
}

if (!action) {
  return [{ json: { error: 'Falta la accion. Use: autorizaciones, cronicidad, o exists.' } }];
}

let apiUrl = '';
const base = 'https://asesores-api.osadef.org.ar';

if (['autorizaciones','autorizacion','medicamentos'].includes(action)) {
  apiUrl = `${base}/autorizaciones?cuil=${cuil}`;
  if (nombre) apiUrl += `&nombre=${encodeURIComponent(nombre)}`;
  if (desde) apiUrl += `&desde=${encodeURIComponent(desde)}`;
  if (hasta) apiUrl += `&hasta=${encodeURIComponent(hasta)}`;
} else if (['cronicidad','cronico','tratamiento','patologia'].includes(action)) {
  apiUrl = `${base}/cronicidad?cuil=${cuil}`;
  if (nombre) apiUrl += `&nombre=${encodeURIComponent(nombre)}`;
  if (venceEnDias) apiUrl += `&vence_en_dias=${encodeURIComponent(venceEnDias)}`;
} else if (['exists','validar','afiliado'].includes(action)) {
  apiUrl = `${base}/afiliados/exists?cuil=${cuil}`;
} else {
  return [{ json: { error: `Accion '${action}' no reconocida. Use: autorizaciones, cronicidad, o exists.` } }];
}

return [{ json: { apiUrl, cuil, action } }];

const apiResponse = $input.first().json;
const action = $vars.action || 'unknown';

if (apiResponse.error) {
  return [{ json: { text: `Error: ${apiResponse.error}` } }];
}

if (apiResponse.exists !== undefined) {
  // Es un exists
  const tipo = apiResponse.tipo || 'afiliado';
  const msg = apiResponse.exists
    ? `El CUIL ${apiResponse.cuil} existe en el sistema como ${tipo}.`
    : `El CUIL ${apiResponse.cuil} no existe en el sistema.`;
  return [{ json: { text: msg, raw: apiResponse } }];
}

if (!apiResponse.data || apiResponse.data.length === 0) {
  return [{ json: { text: 'No se encontraron registros para esta consulta.', raw: apiResponse } }];
}

let text = '';
const items = apiResponse.data;
const count = apiResponse.count || items.length;

if (items[0].numeroautorizacion !== undefined) {
  // Autorizaciones (medicamentos + prácticas)
  const meds = items.filter(i => i.tipo === 'medicamento');
  const pracs = items.filter(i => i.tipo === 'prestacion');

  if (meds.length > 0) {
    text += `**Medicamentos (${meds.length}):**\n`;
    meds.forEach((item, i) => {
      text += `${i + 1}. **${item.nombre || 'Medicamento'}**` +
        (item.potencia ? ` ${item.potencia}mg` : '') +
        ` — Autorizado: ${item.fecha}, Vence: ${item.fechavencimiento}, Cobertura: ${item.cobertura || 'N/A'}%` +
        ` (Cod: ${item.codigo || 'N/A'})\n`;
    });
    text += '\n';
  }

  if (pracs.length > 0) {
    text += `**Prácticas (${pracs.length}):**\n`;
    pracs.forEach((item, i) => {
      text += `${i + 1}. **${item.nombre || 'Práctica'}**` +
        ` — Autorizado: ${item.fecha}, Vence: ${item.fechavencimiento || 'N/A'}` +
        (item.medico ? `, Médico: ${item.medico}` : '') +
        (item.matricula ? ` (MP ${item.matricula})` : '') +
        `\n`;
    });
    text += '\n';
  }
} else if (items[0].cronicidad !== undefined) {
  // Cronicidad
  text = `Encontré ${count} tratamiento(s) cronico(s):\n\n`;
  items.forEach((item, i) => {
    text += `${i + 1}. **${item.cronicidad || 'Patologia'}** — ${item.monodroga || 'Medicamento'}` +
      (item.potencia ? ` ${item.potencia}mg` : '') +
      ` — Cobertura: ${item.cobertura || 'N/A'} — Vence: ${item.fechavencimiento || 'N/A'}\n`;
  });
} else {
  // Generico
  text = `Encontré ${count} resultado(s):\n\n`;
  items.forEach((item, i) => {
    text += `${i + 1}. ${JSON.stringify(item)}\n`;
  });
}

return [{ json: { text, raw: apiResponse } }];
